        mov     ax, [step__k]
        mov     [pending], ax
; ---- return
        ret
.L2399:
; ---- pending = 0
        mov     word [pending], 0
; ---- if ( k == keyQuit ) {
        mov     ax, [step__k]
        cmp     ax, 17
        jne     .L2404                      ; unsigned ==
; ---- tryQuit()
        call    tryQuit
; ---- return
        ret
.L2404:
; ---- if ( a == actNone && had == 0 && k >= 32 && k < keyExt && k != keyCtrlBack ) {
        mov     al, [step__a]
        test    al, al
        jne     .L2407                      ; unsigned ==
        mov     ax, [step__had]
        test    ax, ax
        jne     .L2407                      ; unsigned ==
        mov     ax, [step__k]
        cmp     ax, 32
        jb      .L2407                      ; unsigned >=
        mov     ax, [step__k]
        cmp     ax, 256
        jae     .L2407                      ; unsigned <
        mov     ax, [step__k]
        cmp     ax, 127
        je      .L2407                      ; unsigned !=
; ---- a = actInsert
        mov     byte [step__a], 1
.L2407:
; ---- apply( a, k )
        mov     al, [step__a]
        mov     [apply__a], al              ; u8 -> u8, no widening
        mov     ax, [step__k]
        mov     [apply__k], ax
        call    apply
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int10:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x10
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pushf
        pop     ax
        and     al, 1                       ; carry is bit 0
        mov     [_cf], al
        pop     es
        ret

int16:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x16
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pushf
        pop     ax
        and     al, 1                       ; carry is bit 0
        mov     [_cf], al
        pop     es
        ret

int21:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pushf
        pop     ax
        and     al, 1                       ; carry is bit 0
        mov     [_cf], al
        pop     es
        ret

